import React from 'react';
import { Table, Typography, Row, Col } from 'antd';
import './AntTwoTables.css'; // Import CSS for custom row styling

const { Title } = Typography;

const AntTwoTables = ({ data, dateClassName = 'month-column', incomeClassName = 'money-column-blue' }) => {
    // Filter data into odd and even index tables
    const table1Data = data.filter((_, index) => index % 2 === 0); // Odd indices (0-based)
    const table2Data = data.filter((_, index) => index % 2 !== 0); // Even indices (0-based)


    // Define columns
    const columns = [
        {
            title: 'Date/Time',
            dataIndex: 'datetime', // Updated dataIndex
            key: 'Income', // Updated key
            className: dateClassName // Dynamic className for the Income column
        },
        {
            title: 'Amount',
            dataIndex: 'Income', // Updated dataIndex
            key: 'Income', // Updated key
            className: incomeClassName // Dynamic className for the Income column
        }
    ];

    return (
        <div style={{ padding: '10px' }}>
            <Row gutter={16}>
                {/* Table 1 - Odd Indices */}
                <Col span={12}>
                    <Table
                        dataSource={table1Data}
                        columns={columns}
                        pagination={false}
                        bordered
                        showHeader={false} // Hide header
                        rowClassName={() => 'custom-row'} // Apply custom row style
                    />
                </Col>

                {/* Table 2 - Even Indices */}
                <Col span={12}>
                    <Table
                        dataSource={table2Data}
                        columns={columns}
                        pagination={false}
                        bordered
                        showHeader={false} // Hide header
                        rowClassName={() => 'custom-row'} // Apply custom row style
                    />
                </Col>
            </Row>
        </div>
    );
};

export default AntTwoTables;
