import React, { useEffect, useState } from "react";
import "./AnnualIncome.css";
import { Link } from "react-router-dom";
import { Button, DatePicker, Input, Space, notification, Typography } from "antd";
import CurrencyFormat from "react-currency-format";
import db from "../firebase";
import Chart from "../Chart/BarChart";
import { VNCurrency } from "../Functions";
import dayjs from "dayjs";
import AntTwoTables from "../Utils/AntTwoTables";

const { Title, Text } = Typography;

function AnnualIncome() {
    const [year, setYear] = useState(`Income${dayjs().year()}`);
    const [dateIncome, setdateIncome] = useState(dayjs());
    const [TotalIncomes, setTotalIncomes] = useState([]);
    const [BeforeTotalIncomes, setBeforeTotalIncomes] = useState([]);

    let TotalIncome = TotalIncomes.reduce((prev, cur) => prev + cur.Income, 0);
    let BeforeTotalIncome = BeforeTotalIncomes.reduce((prev, cur) => prev + cur.Income, 0);

    function IncomeTotalPerMonth(i) {
        return TotalIncomes.reduce((prev, cur) => (cur.Month === i ? prev + cur.Income : prev), 0);
    }

    // Fetch data on load and year change
    useEffect(() => {
        fetchIncomeData(year);
        // Extract the numeric part and convert it to an integer, then decrement
        const updatedIncome = parseInt(year.replace(/\D/g, ''), 10) - 1;
        // console.log(`Income${updatedIncome}`)
        fetchIncomeData(`Income${updatedIncome}`, setBeforeTotalIncomes);
    }, [year]);

    const fetchIncomeData = (yearKey, setState = setTotalIncomes) => {
        db.collection(yearKey)
            .orderBy("Month", "asc")
            .orderBy("Day", "asc")
            .onSnapshot((snapshot) => {
                setState(snapshot.docs.map((doc) => doc.data()));
            });
    };

    const handleDateChange = (date) => {
        setdateIncome(date);
    };
    const handleAddIncome = (e) => {
        e.preventDefault();

        // Get the value from the input field
        const incomeValue = document.getElementById("IncomeID").value.replaceAll(",", "").trim();

        // Check if the incomeValue is valid and not empty
        if (!incomeValue || isNaN(parseFloat(incomeValue)) || parseFloat(incomeValue) <= 0) {
            notification.error({
                message: 'Invalid Income',
                description: 'Please enter a valid income amount.',
                placement: 'top',
                duration: 3,
            });
            return; // Stop the function if validation fails
        }

        // Proceed to add data if the income is valid
        db.collection(year).add({
            Income: parseFloat(incomeValue),
            Day: dateIncome.date(),
            Month: dateIncome.month() + 1,
            Year: dateIncome.year(),
        });

        notification.success({
            message: 'Success',
            description: 'Income added successfully.',
            placement: 'top',
            duration: 3,
        });
    };

    const handleYearChange = (newYear) => setYear(`Income${newYear}`);

    function renderYearButton(year) {
        return (
            <Button type="primary" className="ButtonYear"
                    onClick={() => handleYearChange(year)}>
                {year}
            </Button>
        );
    }
    // Create data for the table
    const year_money_data = [...Array(12)].map((_, i) => ({
        datetime: dayjs().month(i).format("MMMM"), // Month name (e.g., January)
        Income: VNCurrency(IncomeTotalPerMonth(i + 1)), // Formatted income value
    }));
    // Convert TotalIncomes to the format required for the table

    const year_money_full_data = TotalIncomes.map((item, index) => ({
        key: index,
        datetime: `${item.Day}/${item.Month}/${item.Year}`, // Date formatted
        Income: VNCurrency(item.Income) // Format Income as currency
    }));


    return (
        <div style={{border: "2px solid #1890ff", width: "430px"}}>
            <div style={{marginBottom: 16, marginLeft: 0, display: 'flex', height: '25px', alignItems: 'center'}}>
                {renderYearButton("2025")}
                {renderYearButton("2024")}
                {renderYearButton("2023")}
                {renderYearButton("2022")}
            </div>
            <div style={{display: "flex", marginLeft: 10, marginBottom: 5}}>
                <Link to="/">
                    <div style={{marginTop: 0, marginRight: 20}}>
                        <span className="Header-cartCount">Main</span>
                    </div>
                </Link>
                <Link to="/AnnuallOutcome">
                    <div style={{marginTop: 0, marginRight: 20}}>
                        <span className="Header-cartCount">Annual Outcome</span>
                    </div>
                </Link>
            </div>

            <div style={{margin: "10px 0", marginLeft: 10, fontWeight: "bold", display: "flex"}}>
                <div style={{fontSize: "14px", width: "110px"}}>Total Income:</div>
                <div style={{fontSize: "14px"}}>{VNCurrency(TotalIncome)}</div>
                <div
                    style={{
                        fontSize: "14px",
                        marginLeft: 10,
                        color: TotalIncome - BeforeTotalIncome > 0 ? 'blue' : 'red' // Màu xanh nếu dương, đỏ nếu âm
                    }}
                >
                    ( {VNCurrency(TotalIncome / 12)}) ({VNCurrency(TotalIncome - BeforeTotalIncome)})
                </div>
            </div>

            {/* Input Area */}
            <div className="input-container">
                <DatePicker value={dateIncome} onChange={handleDateChange} format="MM/DD/YYYY"/>
                <CurrencyFormat
                    id="IncomeID"
                    customInput={Input}
                    thousandSeparator
                    prefix=""
                    style={{width: 150, marginLeft: '12px',}}
                />
                <Button type="primary" className="ButtonStandard" onClick={handleAddIncome}>
                    Add
                </Button>
            </div>

            {/* Chart Income Per Month */}
            <div className="chart-container">
                <Chart
                    data={Array.from({length: 12}, (_, i) => IncomeTotalPerMonth(i + 1))}
                    Total={TotalIncome / 12}
                    MainLabel="Total Income"
                    SubLabel="Income Per Month"
                />
            </div>
            {/* Table Section Income per month*/}
            <AntTwoTables
                data={year_money_data}
                incomeClassName="money-column-blue"  // This will apply the 'blue-money' class to the "Amount" column
                dateClassName="month-column"
            />
            <AntTwoTables
                data={year_money_full_data}
                // incomeClassName="money-column"
                dateClassName="money-column"
            />
        </div>
    );
}

export default AnnualIncome;
