import React, { useEffect, useState, useCallback } from "react";
import Highcharts from "highcharts";
import HighchartsReact from "highcharts-react-official";

// GMT+7
Highcharts.setOptions({
  time: {
    timezoneOffset: -7 * 60
  }
});

// Constants for better readability and maintainability
const API_ENDPOINTS = {
  PLOT_LINE: "https://bgapidatafeed.vps.com.vn/getlistindexdetail/10,02,11,03",
  CHART_DATA: "https://histdatafeed.vps.com.vn/tradingview/historiesnearest?symbols=VNINDEX&props=o,v,t&resolution=1"
};

const VNINDEX_MC_CODE = "10";
const Y_AXIS_PADDING_FACTOR = 0.05;
const UPDATE_INTERVAL_MS = 60000; // 1 minute

const StockChart = () => {
  const [plotLineValue, setPlotLineValue] = useState(null);
  const [chartOptions, setChartOptions] = useState({
    chart: {
      width: 250,
      height: 90,
      backgroundColor: "#1E1E1E",
      plotBackgroundColor: "#1E1E1E",
      spacing: [0, 0, 0, 0],
      margin: [0, 0, 0, 0],
    },
    title: { text: null },
    credits: { enabled: false },
    legend: { enabled: false },
    xAxis: {
      type: "datetime",
      labels: {
        style: { color: "#B0B0B0", fontSize: "9px" }
      },
      lineColor: "#888",
      tickColor: "#888",
      tickPositions: [],
      breaks: []
    },
    yAxis: [{
      title: { text: null },
      labels: { enabled: false },
      gridLineWidth: 0,
      plotLines: [],
      startOnTick: false,
      endOnTick: false
    }],
    series: [],
    tooltip: { enabled: false },
  });

  // Lấy giá mở cửa (plotLine)
  const fetchPlotLine = useCallback(async () => {
    try {
      const response = await fetch(API_ENDPOINTS.PLOT_LINE);
      const data = await response.json();
      if (Array.isArray(data)) {
        const vnindexData = data.find(item => item.mc === VNINDEX_MC_CODE);
        if (vnindexData && vnindexData.oIndex) {
          setPlotLineValue(parseFloat(vnindexData.oIndex));
        }
      }
    } catch (error) {
      console.error("Lỗi lấy dữ liệu plotLine:", error);
    }
  }, []); // No dependencies, so it's stable

  // Lấy dữ liệu biểu đồ VNINDEX
  const fetchChartData = useCallback(async () => {
    try {
      const response = await fetch(API_ENDPOINTS.CHART_DATA);
      const data = await response.json();

      if (data && data.VNINDEX) {
        const { t, o } = data.VNINDEX;

        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = today.getMonth();
        const dd = today.getDate();

        // Optimized date calculations
        const createDate = (hour, minute) => new Date(yyyy, mm, dd, hour, minute).getTime();

        const start9h = createDate(9, 0);
        const start915 = createDate(9, 15);
        const end1445 = createDate(14, 45);

        // Tick cố định
        const ticks = [
          createDate(9, 0),
          createDate(10, 0),
          createDate(11, 0),
          createDate(12, 0),
          createDate(14, 0)
        ];

        // Dữ liệu index
        const indexData = [];

        // Thêm dữ liệu phẳng từ 9h → 9h15
        if (plotLineValue) {
          for (let ts = start9h; ts <= start915; ts += 60000) {
            indexData.push([ts, plotLineValue]);
          }
        }

        // Dữ liệu thực tế
        t.forEach((time, i) => {
          indexData.push([time * 1000, o[i]]);
        });

        // Zones màu
        const zones = plotLineValue
            ? [
              { value: plotLineValue, color: "#FF0000" },
              { color: "#00FF00" }
            ]
            : [{ color: "#00FF00" }];

        // Min/Max X
        const minX = indexData.length ? Math.min(...indexData.map(d => d[0])) : start9h;

        // Min/Max Y để ép sát top-bottom
        const yValues = indexData.map(d => d[1]);
        const minY = Math.min(...yValues);
        const maxY = Math.max(...yValues);
        const padding = (maxY - minY) * Y_AXIS_PADDING_FACTOR;

        setChartOptions(prev => ({
          ...prev,
          xAxis: {
            ...prev.xAxis,
            min: minX,
            max: end1445,
            tickPositions: ticks
          },
          yAxis: [{
            ...prev.yAxis[0],
            min: minY - padding,
            max: maxY + padding,
            plotLines: plotLineValue
                ? [{
                  value: plotLineValue,
                  color: "yellow",
                  dashStyle: "Dash",
                  width: 2,
                  zIndex: 5,
                  label: {
                    text: plotLineValue.toLocaleString("en-US", {
                      minimumFractionDigits: 2,
                      maximumFractionDigits: 2
                    }),
                    align: "center",
                    style: {
                      color: "#FFFFFF",
                      fontWeight: "bold",
                      fontSize: "14px",
                      textOutline: "2px contrast"
                    },
                    y: -5
                  }
                }]
                : [],
          }],
          series: [{
            name: "VNINDEX",
            type: "line",
            data: indexData,
            yAxis: 0,
            color: "#00FF00",
            zones: zones,
            lineWidth: 1.5,
            marker: { enabled: false }
          }]
        }));
      }
    } catch (error) {
      console.error("Lỗi tải dữ liệu biểu đồ:", error);
    }
  }, [plotLineValue]); // Dependency on plotLineValue

  // Fetch plotLineValue once on mount
  useEffect(() => {
    fetchPlotLine();
  }, [fetchPlotLine]);

  // Fetch chart data periodically
  useEffect(() => {
    const updateChartData = async () => {
      await fetchChartData();
    };

    updateChartData();
    const interval = setInterval(updateChartData, UPDATE_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [fetchChartData]);

  return (
      <div style={{ width: "250px", height: "90px", overflow: "hidden" }}>
        <HighchartsReact highcharts={Highcharts} options={chartOptions} />
      </div>
  );
};

export default StockChart;
